"""Направления (регистры) ВСН и правила автоклассификации по названию.

Документ может попасть в несколько направлений. Ручные правки — в
registers/classification_overrides.csv (id;directions), они главнее правил.
"""
import re

# код, файл-регистр, название, важно для ППР
DIRECTIONS = [
    ("LCH", "01_Линейная_часть_МТ",        "Линейная часть магистральных и промысловых трубопроводов", True),
    ("TT",  "02_Технологические_трубопроводы", "Технологические трубопроводы, КС/НС/ГРС, монтаж оборудования, резервуары", True),
    ("SV",  "03_Сварка_и_контроль",        "Сварка, резка, контроль сварных соединений (РК, УЗК)", True),
    ("AKZ", "04_Изоляция_АКЗ_ЭХЗ",         "Изоляция, антикоррозионная защита, ЭХЗ, теплоизоляция", True),
    ("ISP", "05_Испытания_приемка_ИД",     "Очистка полости, испытания, контроль качества, приёмка, исполнительная документация", True),
    ("ZR",  "06_Земляные_работы_основания", "Земляные работы, основания, фундаменты, сваи, мерзлота, рекультивация", True),
    ("BZB", "07_Бетон_и_ЖБ",               "Бетон, железобетон, растворы, сборные ЖБ конструкции", True),
    ("MK",  "08_Металлоконструкции",       "Металлоконструкции, алюминиевые и прочие несущие конструкции", True),
    ("DOR", "09_Дороги_и_аэродромы",       "Автомобильные дороги, временные дороги, аэродромы", True),
    ("MOST","10_Мосты_и_трубы",            "Мосты, путепроводы, водопропускные трубы", False),
    ("GTS", "11_Гидротехника_мелиорация",  "Гидротехнические сооружения, порты, мелиорация, водолазные работы", False),
    ("IS",  "12_Инженерные_сети",          "Водопровод, канализация, тепловые сети, газоснабжение, ОВиК", True),
    ("EL",  "13_Электро_связь_автоматика", "Электроснабжение, освещение, связь, ЛЭП, молниезащита, автоматика, сигнализация", True),
    ("ZD",  "14_Здания_и_отделка",         "Здания и помещения: проектирование, кровли, полы, отделка, стыки панелей", False),
    ("PB",  "15_Пожарная_безопасность",    "Пожарная безопасность, пожаротушение, охрана объектов", True),
    ("OOS", "16_Охрана_окружающей_среды",  "Охрана окружающей среды, рекультивация земель", True),
    ("ORG", "17_Организация_строительства_ПОС_ППР", "Организация строительства, ПОС/ППР, механизация, продолжительность, нормы расхода, сметы и ценники", True),
    ("OT",  "18_Охрана_труда_и_ТБ",        "Охрана труда, техника безопасности, работы в охранных зонах", True),
    ("PROCH","19_Прочие_отрасли",          "Прочие отрасли: железные дороги, энергетика, градостроительство, МО и др.", False),
]
CODES = [d[0] for d in DIRECTIONS]

RULES = {
    "LCH": r"магистральн\w* (?:и промысл\w* )?(?:стальн\w* )?(?:нефте|газо|трубопр|нефтегазо)|промыслов\w* (?:стальн\w* )?трубопр|линейн\w* част|подводн\w* переход|надземн\w* переход|балластир|утяжеляющ|всплыт|газопровод|нефтепровод|трубопроводостр|трубопроводн\w* строител|труб больших диаметров|трасс",
    "TT":  r"технологическ\w* (?:трубопр|оборуд)|компрессорн|насосн\w* станц|трубопровод\w* газообразн|баков|резервуар|кислород|обогрев\w* технолог|монтаж\w* оборуд|тройник",
    "SV":  r"свар|резк|радиограф|ультразвук|снимк",
    "AKZ": r"изоляц|антикорроз|коррози|электрохим|катодн|защитн\w* покрыт|битумн\w*-каучук|пенополиуретан|пенополиэтилен|поропласт|теплоизол|битумоперлит",
    "ISP": r"испытан|очистк\w* полост|контрол\w* качеств|приемк|приемке|сдачи-приемки|документац|отказ|оценк\w* качеств|техническ\w* (?:учет|расследован|обследован)|паспортизац|осмотр|диагност|грузоподъемност|неразрушающ",
    "ZR":  r"земл\w* (?:работ|полотн|сооружен)|земляных|нулевого цикла|грунт|основани|фундамент|сва[ийе]|свая|котлован|мерзл|откос|намывн|водоотлив|цементац|просадочн|набухающ|пучинист|рекультив|дренаж|буровзрыв|подземн\w* (?:работ|сооружен)",
    "BZB": r"бетон|железобетон|раствор|армополимер|цемент|сборн\w* (?:изделий|элемент|конструкц|железобет)|панел",
    "MK":  r"стальн\w* (?:вертикальн|конструкц)|металлическ\w* конструкц|металлоконстр|алюминиев",
    "DOR": r"автомобильн\w* дорог|дорожн|дорог[иа]?\b|дорог |покрыти\w* (?:город|дорог)|асфальт|аэродром|летн\w* пол|тротуар|гравийн|обочин|разметк|скользк|снегозащит|снежн\w* занос",
    "MOST":r"мост|путепровод|пролетн|водопропускн\w* труб|мостов\w* переход",
    "GTS": r"гидротехническ|плотин|морск|речн|причал|порт|канал|оросительн|мелиорат|водохозяйств|водолаз|больверк|заторами|ледостойк|сел[ейя]|туннел|гэс|гаэс",
    "IS":  r"водопровод|канализац|водосток|теплов\w* сет|теплоснабж|газоснабж|отоплен|вентиляц|кондиционир|водоснабж|санитарн|мусоропровод|геотермальн|водостоки",
    "EL":  r"электр|освещен|связ[иь]|линии связи|лэп|молниезащ|контактн\w* сет|автоматик|сигнализац|радиообъект|автоблокир|светосигнал|опрессовк\w* провод",
    "ZD":  r"здани|помещени|жил\w* дом|общежит|кровл|пол(?:ов|ы)\b|отделк|облицов|потолк|перегород|стыков\w* соединен\w* панел|стык\w* панел|звукоизол|солнцезащит|крыш|окон|витраж|линолеум|паркет|шпаклев",
    "PB":  r"пожар|взрывопожар|взрывоопасн|охранн|охран\w* (?:сигнал|предприят|объект)|инженерно-технических средств охраны|пожаротуш",
    "OOS": r"окружающ\w* сред|охран\w* природ|рекультивац|землепользован|лесонасажд|лесн\w* полос",
    "ORG": r"организац\w* (?:строит|и механиз|и производ|движени)|проект\w* (?:организац|производств)|производств\w* работ|продолжительност|задел|норм\w* расход|расход\w* (?:материал|основн)|сметн|расценок|ценник|техническ\w* оснащ|механизирован|механизац|эксплуатац\w* (?:дорожно|машин)|ремонт\w* (?:дорожн|машин|оборудован)|техническ\w* обслуживан|перевозк|погрузк|складирован|баллон|разбивочн|геодезическ|изыскан",
    "OT":  r"техник\w* безопасност|безопасн\w* (?:ведени|организац|при )|охранн\w* зон|правила безопасност",
    "PROCH":r"железнодорож|железн\w* дорог|вокзал|электрификац\w* железн|атомн|тепловых электр|электростанц|градостро|планировк|застройк|курорт|военн|минобороны|мо ссср|мо рф|оборон|лесозаготов|лесохозяйств|доменн|спорт|библиотек|престарел|дошкольн|пионерск|профилактор|тир|лыжн|спиртов|горн|горнодобыва|элеватор|сельск|цветн\w* металлург|нефтеперерабат|нефтехим|химическ\w* промышлен|скважин|месторожден",
}
_RX = {k: re.compile(v, re.I) for k, v in RULES.items()}


def classify(title: str) -> list:
    t = title.lower().replace("ё", "е")
    found = [c for c in CODES if _RX[c].search(t)]
    return found or ["PROCH"]
